def layer8(mask):
 d=np.full(mask.shape,-1,int);q=deque()
 H,W=mask.shape
 for r,c in zip(*np.where(mask)):
  if any(not(0<=r+dr<H and 0<=c+dc<W) or not mask[r+dr,c+dc] for dr in [-1,0,1] for dc in [-1,0,1] if dr or dc):d[r,c]=0;q.append((r,c))
 while q:
  r,c=q.popleft()
  for dr in [-1,0,1]:
   for dc in [-1,0,1]:
    if not (dr or dc):continue
    rr,cc=r+dr,c+dc
    if 0<=rr<H and 0<=cc<W and mask[rr,cc] and d[rr,cc]<0:d[rr,cc]=d[r,c]+1;q.append((rr,cc))
 return d
